import React, { useState, useEffect, useRef } from 'react';
import ConveyorBelt from '../ConveyorBelt/ConveyorBelt';
import TrafficLight from '../TrafficLight/TrafficLight';
import Sensor from '../Sensor/Sensor';
import './Dashboard.css';

const SENSOR_POSITION = 70;   // % position that triggers the sensor
const PAUSE_DURATION  = 1500; // ms an item pauses at the sensor
const TICK_MS         = 50;   // interval between simulation ticks

function makeItems() {
  return [
    { id: 1, position:  5, paused: false, pausedAt: null, hasPassedSensor: false },
    { id: 2, position: 40, paused: false, pausedAt: null, hasPassedSensor: false },
    { id: 3, position: 75, paused: false, pausedAt: null, hasPassedSensor: true  },
  ];
}

export default function Dashboard() {
  const [items,         setItems]         = useState(makeItems());
  const [isRunning,     setIsRunning]     = useState(false);
  const [hasEverStarted,setHasEverStarted]= useState(false);
  const [speed,         setSpeed]         = useState(0.8);

  const speedRef = useRef(speed);
  useEffect(() => { speedRef.current = speed; }, [speed]);

  // ── Derived values ────────────────────────────────────────────────────────
  const sensorActive = items.some((item) => item.paused);

  let lightColor;
  if (sensorActive) {
    lightColor = 'red';
  } else if (!isRunning) {
    lightColor = hasEverStarted ? 'yellow' : 'red';
  } else {
    lightColor = 'green';
  }

  // ── Simulation tick ───────────────────────────────────────────────────────
  useEffect(() => {
    if (!isRunning) return;

    const interval = setInterval(() => {
      const now = Date.now();

      setItems((prev) =>
        prev.map((item) => {
          // Paused item: check if pause duration has elapsed
          if (item.paused) {
            if (now - item.pausedAt >= PAUSE_DURATION) {
              return { ...item, paused: false, pausedAt: null };
            }
            return item;
          }

          let newPos = item.position + speedRef.current;

          // Wrap around: item exits right, re-enters from left
          if (newPos > 108) {
            return { ...item, position: -8, hasPassedSensor: false };
          }

          // First time crossing the sensor position → pause
          if (newPos >= SENSOR_POSITION && !item.hasPassedSensor) {
            return {
              ...item,
              position: SENSOR_POSITION,
              paused: true,
              pausedAt: now,
              hasPassedSensor: true,
            };
          }

          return { ...item, position: newPos };
        })
      );
    }, TICK_MS);

    return () => clearInterval(interval);
  }, [isRunning]);

  // ── Controls ──────────────────────────────────────────────────────────────
  const handleStart = () => {
    setIsRunning(true);
    setHasEverStarted(true);
  };

  const handleStop = () => {
    setIsRunning(false);
  };

  const handleReset = () => {
    setIsRunning(false);
    setHasEverStarted(false);
    setItems(makeItems());
  };

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <div className="dashboard">
      {/* ── Header ── */}
      <div className="dashboard__header">
        <div className="dashboard__header-badge">INDUSTRIE v1.0</div>
        <h1 className="dashboard__title">FÖRDERBAND-STEUERUNG</h1>
        <div className={`dashboard__run-indicator ${isRunning ? 'dashboard__run-indicator--on' : ''}`}>
          {isRunning ? '● LÄUFT' : '○ GESTOPPT'}
        </div>
      </div>

      {/* ── Main content ── */}
      <div className="dashboard__content">
        {/* Sidebar: TrafficLight + Sensor + Stats */}
        <div className="dashboard__sidebar">
          <TrafficLight color={lightColor} />

          <div className="dashboard__divider" />

          <Sensor active={sensorActive} position={SENSOR_POSITION} />

          <div className="dashboard__divider" />

          <div className="dashboard__stats">
            <div className="dashboard__stat">
              <span className="dashboard__stat-label">ITEMS</span>
              <span className="dashboard__stat-value">{items.length}</span>
            </div>
            <div className="dashboard__stat">
              <span className="dashboard__stat-label">SPEED</span>
              <span className="dashboard__stat-value">{speed.toFixed(1)}x</span>
            </div>
            <div className="dashboard__stat">
              <span className="dashboard__stat-label">SIGNAL</span>
              <span
                className={`dashboard__stat-value ${
                  lightColor === 'red'    ? 'text-red'    :
                  lightColor === 'green'  ? 'text-green'  : 'text-yellow'
                }`}
              >
                {lightColor.toUpperCase()}
              </span>
            </div>
            <div className="dashboard__stat">
              <span className="dashboard__stat-label">PAUSED</span>
              <span className="dashboard__stat-value">
                {items.filter((i) => i.paused).length}
              </span>
            </div>
          </div>
        </div>

        {/* Belt area */}
        <div className="dashboard__belt-area">
          <div className="dashboard__belt-header">
            <span className="dashboard__belt-title">FÖRDERBAND A1</span>
            <span className="dashboard__belt-sensor-note">Sensor bei {SENSOR_POSITION}%</span>
          </div>
          <ConveyorBelt
            items={items}
            sensorPosition={SENSOR_POSITION}
            isRunning={isRunning}
          />
        </div>
      </div>

      {/* ── Controls ── */}
      <div className="dashboard__controls">
        <div className="dashboard__buttons">
          <button
            className="btn btn--start"
            onClick={handleStart}
            disabled={isRunning}
          >
            ▶ START
          </button>
          <button
            className="btn btn--stop"
            onClick={handleStop}
            disabled={!isRunning}
          >
            ■ STOP
          </button>
          <button
            className="btn btn--reset"
            onClick={handleReset}
          >
            ↺ RESET
          </button>
        </div>

        <div className="dashboard__speed-control">
          <label className="dashboard__speed-label">
            <span>GESCHWINDIGKEIT</span>
            <span className="dashboard__speed-value">{speed.toFixed(1)}</span>
          </label>
          <input
            type="range"
            className="dashboard__speed-slider"
            min="0.2"
            max="2.0"
            step="0.1"
            value={speed}
            onChange={(e) => setSpeed(parseFloat(e.target.value))}
          />
          <div className="dashboard__speed-marks">
            <span>LANGSAM</span>
            <span>SCHNELL</span>
          </div>
        </div>
      </div>

      {/* ── Footer warning stripe ── */}
      <div className="dashboard__warning-stripe" />
    </div>
  );
}
